const startMs   = $('Record Start Time').item.json.start_time_ms;
const inputText = $('Record Start Time').item.json.input_text;
const inputTok  = $('Record Start Time').item.json.input_token_estimate;
const s1Text = $('Stage 1 - Answer Agent').item.json.text || '';
const s1Tok  = $('Compute Stage 1 Tokens').item.json.stage1_token_estimate || 0;
const s2Text = $('Stage 2 - Calculator').item.json.text || '';
const s3Text = $input.first().json.text || '';
const endMs         = Date.now();
const latency_ms    = endMs - startMs;
const s2Tok         = Math.ceil(s2Text.length / 4);
const s3Tok         = Math.ceil(s3Text.length / 4);
const totalInputTok  = inputTok + s1Tok;
const totalOutputTok = s1Tok + s2Tok + s3Tok;
const totalTok       = totalInputTok + s2Tok + s3Tok;
const s3Words        = s3Text.split(/\s+/).filter(w => w.length > 0).length;
const s1HasBullets   = /^[-\u2022*]\s/m.test(s1Text);
const didCalc        = !s2Text.trim().startsWith('NO_CALCULATIONS_REQUIRED');
return [{
  json: {
    user_prompt:  inputText,
    final_answer: s3Text,
    metadata: {
      pattern:          'Sequential Pipeline',
      pattern_category: 'Deterministic Workflow Pattern',
      run_timestamp:    new Date().toISOString(),
      model:            'qwen2.5:14b',
      model_provider:   'Ollama (local)',
      temperature:      0.7,
      latency_ms:       latency_ms,
      latency_seconds:  parseFloat((latency_ms / 1000).toFixed(2)),
      llm_calls_actual: 3,
      llm_calls_max:    3,
      token_usage: {
        total_input_tokens:  totalInputTok,
        total_output_tokens: totalOutputTok,
        total_tokens:        totalTok
      },
      status:            'completed',
      termination_reason: 'all_stages_completed'
    },
    execution_trace: {
      gate_decision:         'PASS',
      gate_logic:            'Stage 1 token estimate >= 30 AND output != INSUFFICIENT_INPUT',
      stage1_token_estimate: s1Tok,
      stage_outputs: {
        stage1_answer:     s1Text,
        stage2_calculator: s2Text,
        stage3_final:      s3Text
      },
      quality_checks: {
        stage1_uses_bullets:           s1HasBullets,
        stage2_performed_calculations: didCalc,
        stage3_word_count:             s3Words,
        all_stages_completed:          s1Text.length > 0 && s2Text.length > 0 && s3Text.length > 0
      }
    }
  }
}];

const startMs       = $('Record Start Time').item.json.start_time_ms;
const inputText     = $('Record Start Time').item.json.input_text;
const inputTok      = $('Record Start Time').item.json.input_token_estimate;
const s1Tok         = $('Compute Stage 1 Tokens').item.json.stage1_token_estimate;
const s1Text        = $('Stage 1 - Answer Agent').item.json.text || '';
const isInsufficient= $('Compute Stage 1 Tokens').item.json.stage1_is_insufficient;
const latency_ms    = Date.now() - startMs;
return [{
  json: {
    user_prompt:  inputText,
    final_answer: s1Text,
    metadata: {
      pattern:          'Sequential Pipeline',
      pattern_category: 'Deterministic Workflow Pattern',
      run_timestamp:    new Date().toISOString(),
      model:            'qwen2.5:14b',
      model_provider:   'Ollama (local)',
      temperature:      0.7,
      latency_ms:       latency_ms,
      latency_seconds:  parseFloat((latency_ms / 1000).toFixed(2)),
      llm_calls_actual: 1,
      llm_calls_max:    3,
      token_usage: {
        total_input_tokens:  inputTok,
        total_output_tokens: s1Tok,
        total_tokens:        inputTok + s1Tok
      },
      status:            'gate_rejected',
      termination_reason: isInsufficient
        ? 'stage1_returned_insufficient_input'
        : 'stage1_token_count_below_threshold'
    },
    execution_trace: {
      gate_decision:          'REJECT',
      gate_logic:             'Stage 1 token estimate >= 30',
      stage1_token_estimate:  s1Tok,
      stage1_is_insufficient: isInsufficient,
      stage1_raw_output:      s1Text,
      rq3_note:               'Gate blocked - only 1 of 3 LLM calls was made'
    }
  }
}];
